import { extractInlineRefMentions } from "../../session-logs/inline-refs.js";
/** The metadata of a row, with a column that is absent or empty left out. */
export function toMeta(r, sessionId) {
    return {
        sessionId,
        startedAt: typeof r.time_created === "number" ? r.time_created : undefined,
        endedAt: typeof r.time_updated === "number" ? r.time_updated : undefined,
        projectHint: typeof r.directory === "string" && r.directory.length > 0 ? r.directory : undefined,
        title: typeof r.title === "string" && r.title.length > 0 ? r.title : undefined,
    };
}
/** Listing needs only `session`; reading a session needs `message` and `part`, and fails loudly without them. */
export const V1_TABLES = ["session"];
/** Every V1 session updated at or after `sinceMs`, newest first. Throws on an incompatible schema. */
export function listV1Sessions(db, sinceMs) {
    const rows = db
        .prepare("SELECT id, title, directory, time_created, time_updated FROM session WHERE time_updated >= ? ORDER BY time_updated DESC")
        .all(sinceMs);
    return rows.map((r) => toMeta(r, r.id));
}
/**
 * One event per message, text-parts concatenated in time order. Throws on an
 * incompatible schema or a session that is not in the file; individual unparsable
 * rows are skipped.
 */
export function readV1Session(db, harness, sessionId, filePath) {
    const meta = db
        .prepare("SELECT title, directory, time_created, time_updated FROM session WHERE id = ?")
        .get(sessionId);
    if (!meta)
        throw new Error(`session ${sessionId} is not in the file`);
    const messages = db
        .prepare("SELECT id, data, time_created FROM message WHERE session_id = ? ORDER BY time_created ASC, id ASC")
        .all(sessionId);
    const parts = db
        .prepare("SELECT message_id, data FROM part WHERE session_id = ? ORDER BY time_created ASC, id ASC")
        .all(sessionId);
    const textByMessage = new Map();
    for (const part of parts) {
        let parsed;
        try {
            parsed = JSON.parse(part.data);
        }
        catch {
            continue;
        }
        if (parsed?.type !== "text")
            continue;
        const text = parsed.text;
        if (typeof text !== "string" || text.length < 1)
            continue;
        const bucket = textByMessage.get(part.message_id) ?? [];
        bucket.push(text);
        textByMessage.set(part.message_id, bucket);
    }
    const events = [];
    const inlineRefs = [];
    for (const message of messages) {
        let mdata = {};
        try {
            mdata = JSON.parse(message.data);
        }
        catch {
            // role/timing unavailable — fall through with defaults
        }
        const role = typeof mdata.role === "string" ? mdata.role : "unknown";
        const mtime = mdata.time?.created;
        const ts = typeof mtime === "number" ? mtime : typeof message.time_created === "number" ? message.time_created : undefined;
        const text = (textByMessage.get(message.id) ?? []).join("\n").trim();
        if (text.length < 1)
            continue;
        events.push({ harness, text, ts, sessionId, role, filePath });
        inlineRefs.push(...extractInlineRefMentions(text, ts));
    }
    events.sort((a, b) => (a.ts ?? 0) - (b.ts ?? 0));
    return { meta: toMeta(meta, sessionId), events, inlineRefs };
}
